import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import{grove,terminal}from'./connectors.js';import{TerminalPlug}from'./TerminalPlug.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';
function board(host){const s=new THREE.Shape(),x=10.35,r=3.6,row=-4,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5.5,-14.4);s.lineTo(-8.7,-14.4);s.lineTo(-x,-12.8);s.lineTo(-x,row-dy);s.absarc(-8,row,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,12.8);s.lineTo(-8.8,14.4);s.lineTo(8.8,14.4);s.lineTo(x,12.8);s.lineTo(x,row+dy);s.absarc(8,row,r,a,Math.PI*2-a,false);s.lineTo(x,-12.8);s.lineTo(8.7,-14.4);s.lineTo(5.5,-14.4);s.lineTo(5.5,-9.5);s.lineTo(-5.5,-9.5);s.closePath();const h=new THREE.Path();h.absarc(0,row,1.8,0,Math.PI*2,false);s.holes.push(h);const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0x386148,{roughness:.89}),[0,0,-1.2],'Unit3.96 passive carrier PCB with real retaining bore,mounting reliefs and Grove notch');pcb.userData={role:'physical-pcb',inferred:true};const pads=[],metal=materials.metal(0xb7b8a8,{roughness:.51});for(const x of spec.terminal.pinX){const p=slab(host.body,1.45,1.45,.08,.25,[x,6.9,-.4],metal,[],.005);p.name='Unit3.96 fixed header physical PCB solder land';pads.push(p);}return{pcb,pads};}
export function buildUnit396(host,{terminalPlug=host.options.terminalPlug??false,terminalPlugAnglesDeg=host.options.terminalPlugAnglesDeg??[0,0,0,0]}={}){if(typeof terminalPlug!=='boolean')throw new TypeError('terminalPlug must be true or false');const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.8})}),pcb=board(host),input=grove(host),output=terminal(host),fixing=screw(host.body,[0,-4,-3.98],'back',1.25);fixing.name='Unit3.96 fixed recessed rear retaining screw';mesh(host.body,new THREE.CylinderGeometry(.6,.6,5.8,24).rotateX(Math.PI/2),materials.metal(0xa3a89c),[0,-4,-.45],'Unit3.96 concealed fixed retaining shank');const back=slab(host.body,...spec.label.back.size,.08,.08,spec.label.back.position,materials.plastic(0xdedfd8,{roughness:.88}),[],.005);back.name='Unit3.96 physical back adhesive film seated on native closed wall';back.userData={role:'physical-label-substrate',face:'back'};host.unit396Assembly={parts,pcb,input,output,fixing,labels:{back}};host.unitStickers=addStickers(host);if(terminalPlug)output.port.attach(new TerminalPlug({anglesDeg:terminalPlugAnglesDeg,artwork:host.options.artwork}));}
